-- 26_ruas_bairros_teofilo_otoni.sql
-- Base oficial CNEFE/IBGE (Teófilo Otoni - MG | IBGE: 3168606)
-- Ruas que atravessam 2 ou mais bairros aparecem vinculadas a cada bairro correspondente.

create table if not exists public.cidade_ruas (
  id uuid primary key default gen_random_uuid(),
  cidade_ibge varchar(7) not null,
  bairro text not null,
  bairro_normalizado text not null,
  logradouro text not null,
  logradouro_normalizado text not null,
  cep varchar(9),
  distrito_sede boolean not null default true,
  unique (cidade_ibge, bairro_normalizado, logradouro_normalizado)
);

create index if not exists idx_cidade_ruas_busca
  on public.cidade_ruas (cidade_ibge, logradouro_normalizado);

on conflict (cidade_ibge, bairro_normalizado, logradouro_normalizado) do nothing;
